<script setup lang="ts">
import {ref,reactive,onMounted,computed,inject} from 'vue'
import {ShieldCheck,RefreshCw,Download,X} from 'lucide-vue-next'
import {api,session,label,date,describeError,type Data} from '../api'
const notify=inject<(s:string,e?:boolean)=>void>('notify')!,admin=computed(()=>session.user?.role==='ADMIN'&&session.user?.status==='NORMAL')
const reports=ref<Data[]>([]),audit=ref<Data[]>([]),delivery=ref<Data[]>([]),statistics=ref<Data|null>(null),activities=ref<Data[]>([]),tab=ref('reports'),error=ref(''),busy=ref(false),modal=ref<{report:Data,kind:string,appeal?:Data}|null>(null)
const form=reactive({reason:'',evidence:'',action:'DISMISS',evidenceReviewed:false,activityId:'',result:'UPHELD'}),filters=reactive({from:'',to:'',type:''})
const metrics:Record<string,string>={published:'已发布需求',submittedRounds:'申请轮次',approvedRounds:'通过轮次',applicationConversion:'申请转化率',dueActivities:'应结束活动',endedActivities:'正常结束',cancelledActivities:'已取消活动',completionRate:'活动完成率',snapshotMembers:'结束快照人数',completedFeedback:'自报完成反馈',feedbackRate:'反馈完成比例',confirmedNoShows:'人工确认失约',noShowRate:'失约率',reports:'举报数量',lateReports:'受理超时',reportOverdueRate:'受理超时比例'}
function query(){return new URLSearchParams(Object.fromEntries(Object.entries(filters).filter(([,v])=>v).map(([k,v])=>[k,k==='type'?v:new Date(v).toISOString()]))).toString()}
async function load(){busy.value=true;error.value='';try{reports.value=await api(admin.value?'/admin/reports':'/reports');if(admin.value){const [s,d,a]=await Promise.all([api('/admin/statistics?'+query()),api('/admin/delivery'),api('/admin/audit')]);statistics.value=s;delivery.value=d;audit.value=a;activities.value=(await api('/activities?pageSize=50')).items}}catch(e){error.value=describeError(e)}finally{busy.value=false}}
onMounted(load)
function choose(report:Data,kind:string,appeal?:Data){modal.value={report,kind,appeal};Object.assign(form,{reason:'',evidence:'',action:'DISMISS',evidenceReviewed:false,activityId:'',result:'UPHELD'});error.value=''}
const allowed=computed(()=>modal.value?.report.targetType==='ACTIVITY'?['DISMISS','HIDE_ACTIVITY','CANCEL_ACTIVITY','DISSOLVE_GROUP']:modal.value?.report.targetType==='MESSAGE'?['DISMISS','HIDE_MESSAGE']:['DISMISS','DISABLE_USER','REMOVE_MEMBER','CONFIRM_NO_SHOW'])
const modalTitle=computed(()=>({acceptance:'受理举报',processing:'进入处理',decision:'形成处置决定',appeal:'提出申诉',review:'申诉复核'}[modal.value?.kind||'']||'处理举报'))
async function submit(){if(!modal.value)return;busy.value=true;error.value='';const {report:r,kind,appeal:a}=modal.value;try{let path=`/admin/reports/${r.id}/${kind}`,body:Data={expectedVersion:r.version,reason:form.reason};if(kind==='decision')Object.assign(body,{action:form.action,evidenceReviewed:form.evidenceReviewed,...(form.activityId?{activityId:form.activityId}:{})});if(kind==='appeal'){path=`/reports/${r.id}/appeals`;body={reason:form.reason,evidence:form.evidence}}if(kind==='review'){path=`/admin/appeals/${a!.id}/decision`;body={expectedVersion:a!.version,result:form.result,reason:form.reason}}
 await api(path,'POST',body,kind==='decision');notify('处理结果已保存，并记录审计');modal.value=null;await load()}catch(e){error.value=describeError(e)}finally{busy.value=false}}
function value(k:string,v:any){return v===null?'暂无分母':k.endsWith('Rate')||k==='applicationConversion'?`${(v*100).toFixed(1)}%`:v}
const deliveryNames:Record<string,string>={READY:'等待投递',RUNNING:'正在投递',RETRY:'待重试',FAILED:'投递失败',ACCEPTED:'渠道已受理',OBSOLETE:'提醒已过时',QUARANTINED:'版本已隔离'}
</script>
<template><div class="page-heading"><div><span class="eyebrow">FAIRNESS MAKES TRUST POSSIBLE</span><h1>{{admin?'治理与统计':'举报与申诉'}}</h1><p>{{admin?'按证据处理争议，保留每一次决定的依据。':'查看你的举报进度，对相关处置提出申诉。'}}</p></div><button class="secondary" @click="load"><RefreshCw :size="16"/>刷新</button></div><div v-if="admin" class="tabs"><button v-for="n in [{id:'reports',name:'举报处理'},{id:'statistics',name:'运营统计'},{id:'audit',name:'审计记录'},{id:'delivery',name:'通知投递'}]" :key="n.id" :class="['chip',{active:tab===n.id}]" @click="tab=n.id">{{n.name}}</button></div><div v-if="error&&!modal" class="error-box" role="alert">{{error}}</div>
<template v-if="tab==='reports'"><p class="field-help">可在活动详情、小组成员或具体消息处发起举报。人工处置需核验具体证据；单方评价不自动认定失约。</p><section class="stack"><article v-for="r in reports" :key="r.id" class="panel"><div class="row-between"><div class="actions"><span class="badge">{{r.targetType==='ACTIVITY'?'活动举报':r.targetType==='USER'?'成员举报':'消息举报'}}</span><span class="badge">{{label(r.status)}}</span><span v-if="r.overdue" class="category MEAL">受理超过24小时</span></div><span class="subtle">{{date(r.createdAt)}}</span></div><h3 class="report-reason" style="margin-top:18px">{{r.reason}}</h3><p v-if="r.evidence" class="report-reason muted">证据说明：{{r.evidence}}</p><p v-if="r.decision" class="warning-box">处置：{{label(r.decision.action)}}{{r.decision.revoked?'（已撤销）':''}}<br>{{r.decision.reason}}</p><p class="subtle">举报编号 {{r.id}}</p><div class="actions"><template v-if="admin"><button v-if="r.status==='SUBMITTED'" class="primary" @click="choose(r,'acceptance')">受理举报</button><button v-if="r.status==='ACCEPTED'" class="primary" @click="choose(r,'processing')">开始处理</button><button v-if="r.status==='PROCESSING'" class="primary" @click="choose(r,'decision')">作出处置</button></template><button v-if="['RESOLVED','APPEAL_RESOLVED'].includes(r.status)&&(!admin||r.reporterId===session.user?.id||r.targetId===session.user?.id)" class="secondary" @click="choose(r,'appeal')">提出申诉</button></div><div v-for="a in r.appeals" :key="a.id" class="report-form"><h4>申诉 · {{label(a.status)}}</h4><p class="report-reason">{{a.reason}}</p><p v-if="a.evidence" class="muted">{{a.evidence}}</p><p v-if="a.result" class="muted">复核意见：{{a.result}}</p><button v-if="admin&&a.status==='SUBMITTED'" class="secondary" @click="choose(r,'review',a)">复核申诉</button></div></article><div v-if="!reports.length&&!busy&&!error" class="empty-state"><ShieldCheck :size="35"/><h2>暂时没有相关举报</h2><p>每次争议都应有公平、可追溯的处理。</p></div></section></template>
<template v-if="tab==='statistics'&&admin"><form class="panel form-grid" @submit.prevent="load"><label>时间范围自<input v-model="filters.from" type="datetime-local"/></label><label>时间范围至（不含）<input v-model="filters.to" type="datetime-local"/></label><label>活动类型<select v-model="filters.type"><option value="">全部类型</option><option v-for="t in ['STUDY','SPORT','TRAVEL','MEAL','OTHER']" :key="t" :value="t">{{label(t)}}</option></select></label><div class="actions"><button class="primary" :disabled="busy">查询统计</button><a class="secondary" :href="'/api/v1/admin/statistics/export?'+query()" download><Download :size="16"/>脱敏导出</a></div></form><div v-if="statistics" class="stats-grid"><div v-for="(name,k) in metrics" :key="k" class="stat"><small>{{name}}</small><strong>{{value(k,statistics[k])}}</strong></div></div><div class="panel muted"><h3>指标口径</h3><p>发布量按创建时间；申请转化 = 通过轮次 / 提交轮次，均使用同一发布活动队列。</p><p>活动完成率 = 正常结束活动 / 窗口内应结束活动，取消活动计入分母。反馈与失约以结束快照人数为分母。</p><p>失约只计人工确认且未撤销的唯一活动与成员组合。零分母显示「暂无分母」。导出仅包含聚合指标。</p></div></template>
<section v-if="tab==='audit'&&admin" class="panel"><h2>不可变审计记录</h2><article v-for="a in audit" :key="a.id" class="list-row"><div class="row-between"><strong>{{label(a.action)}}</strong><span class="subtle">{{date(a.createdAt)}}</span></div><p>{{a.reason}}</p><p class="subtle">资源 {{a.resourceId}} · 请求 {{a.requestId}}</p></article><p v-if="!audit.length" class="muted">尚无治理操作。</p></section>
<section v-if="tab==='delivery'&&admin" class="panel"><h2>外部通知投递</h2><p class="muted">当前使用模拟渠道。失败任务按 5 / 30 / 60 秒退避，最多尝试30次；站内通知独立保留。</p><div class="stats-grid"><div v-for="d in delivery" :key="d.status" class="stat"><small>{{deliveryNames[d.status]}}</small><strong>{{d.count}}</strong></div></div><p class="field-help">“渠道已受理”不等于终端送达或用户已读。失败与未知版本隔离需要维护人员检查。</p></section>
<div v-if="modal" class="modal-backdrop" @click.self="modal=null"><form class="modal stack" role="dialog" aria-modal="true" @submit.prevent="submit"><button type="button" class="modal-close icon-button" aria-label="关闭治理表单" @click="modal=null"><X/></button><h2>{{modalTitle}}</h2><p class="muted">{{modal.report.reason}}</p><template v-if="modal.kind==='decision'"><label>处置动作<select v-model="form.action"><option v-for="v in allowed" :key="v" :value="v">{{label(v)}}</option></select></label><label v-if="['REMOVE_MEMBER','CONFIRM_NO_SHOW'].includes(form.action)">关联活动<select v-model="form.activityId" required><option value="">请选择经核实的活动</option><option v-for="a in activities" :key="a.id" :value="a.id">{{a.title}} · {{date(a.startAt)}}</option></select></label><label v-if="form.action!=='DISMISS'" class="check-label"><input v-model="form.evidenceReviewed" type="checkbox" required/>已核验具体证据，决定不只依据单方评价</label></template><label v-if="modal.kind==='review'">复核结论<select v-model="form.result"><option value="UPHELD">维持处置</option><option value="REVOKED">撤销处置</option></select></label><label>具体理由与核验依据<textarea v-model="form.reason" required maxlength="1000"></textarea></label><label v-if="modal.kind==='appeal'">补充证据<textarea v-model="form.evidence" maxlength="2000"></textarea></label><div v-if="error" class="error-box" role="alert">{{error}}</div><div class="modal-actions"><button class="secondary" type="button" @click="modal=null">返回</button><button class="primary" :disabled="busy">{{busy?'正在提交…':'确认提交'}}</button></div></form></div>
</template>
